/**
 * HisabKitab 360 - Sales Staff Automated Commission & Incentive Engine
 * --------------------------------------------------------------------
 * Accurately calculates monthly sales volume, earned commission %,
 * target-based performance bonuses, and consolidated payroll disbursement.
 */

/**
 * Calculates the total sales volume generated by an employee across
 * POS salesHistory and delivered fieldOrders.
 * 
 * @param {Object} employee 
 * @param {Array} salesHistory 
 * @param {Array} fieldOrders 
 * @param {string} [monthFilter] - YYYY-MM format, defaults to current month
 * @returns {Object} sales metrics
 */
export const calculateStaffSalesMetrics = (employee, salesHistory = [], fieldOrders = [], monthFilter = null) => {
  if (!employee) {
    return {
      totalSalesAmount: 0,
      salesCount: 0,
      fieldOrdersAmount: 0,
      fieldOrdersCount: 0,
      aggregateSales: 0
    };
  }

  const currentMonth = monthFilter || new Date().toISOString().slice(0, 7); // e.g. '2026-11'
  const empNameLower = (employee.name || '').trim().toLowerCase();
  const empIdStr = String(employee.id || '').trim();

  // 1. Calculate matching POS sales from salesHistory
  let posSalesTotal = 0;
  let posSalesCount = 0;

  (salesHistory || []).forEach(sale => {
    if (!sale) return;
    // Check if within the target month (date string starts with YYYY-MM)
    const saleDate = sale.date || sale.timestamp || '';
    if (monthFilter && !saleDate.startsWith(monthFilter)) return;

    // Match cashier / operator / salesman
    const cashierNameLower = (sale.cashierName || sale.operatorName || sale.staffName || '').trim().toLowerCase();
    const cashierIdStr = String(sale.cashierId || sale.staffId || '').trim();

    const isMatch = (
      (empIdStr && cashierIdStr && empIdStr === cashierIdStr) ||
      (empNameLower && cashierNameLower && (cashierNameLower === empNameLower || cashierNameLower.includes(empNameLower)))
    );

    if (isMatch) {
      posSalesTotal += Number(sale.finalTotal ?? sale.totalAmount ?? sale.total ?? 0);
      posSalesCount++;
    }
  });

  // 2. Calculate matching delivered field orders
  let fieldOrdersTotal = 0;
  let fieldOrdersDeliveredCount = 0;

  (fieldOrders || []).forEach(order => {
    if (!order) return;
    const orderDate = order.orderDate || order.createdAt || '';
    if (monthFilter && !orderDate.startsWith(monthFilter)) return;

    const orderEmpIdStr = String(order.employeeId || '').trim();
    const orderEmpNameLower = (order.employeeName || '').trim().toLowerCase();

    const isEmpMatch = (
      (empIdStr && orderEmpIdStr && empIdStr === orderEmpIdStr) ||
      (empNameLower && orderEmpNameLower && orderEmpNameLower === empNameLower)
    );

    if (isEmpMatch && order.deliveryStatus === 'delivered') {
      const orderSubtotal = (order.items || []).reduce((sum, it) => sum + (Number(it.deliveredQty || it.orderedQty || 0) * Number(it.price || 0)), 0);
      fieldOrdersTotal += (Number(order.totalAmount) || orderSubtotal);
      fieldOrdersDeliveredCount++;
    }
  });

  const aggregateSales = posSalesTotal + fieldOrdersTotal;

  return {
    totalSalesAmount: Math.round(posSalesTotal),
    salesCount: posSalesCount,
    fieldOrdersAmount: Math.round(fieldOrdersTotal),
    fieldOrdersCount: fieldOrdersDeliveredCount,
    aggregateSales: Math.round(aggregateSales)
  };
};

/**
 * Calculates net salary, commission, and incentives for a staff member.
 * 
 * @param {Object} employee 
 * @param {number} aggregateSales 
 * @returns {Object} financial breakdown
 */
export const computeStaffPayBreakdown = (employee, aggregateSales = 0) => {
  const baseSalary = Number(employee?.baseSalary) || 0;
  const commissionRate = Number(employee?.commissionRate) || 0; // percentage, e.g. 2 means 2%

  // Commission earned
  const commissionEarned = commissionRate > 0
    ? Math.round((aggregateSales * commissionRate) / 100)
    : 0;

  // Optional target incentive bonus (e.g. if sales exceed monthly target)
  const salesTarget = Number(employee?.salesTarget) || 0;
  const targetMet = salesTarget > 0 && aggregateSales >= salesTarget;
  const targetBonus = targetMet ? (Number(employee?.targetBonus) || 0) : 0;

  const totalGrossPayable = baseSalary + commissionEarned + targetBonus;

  return {
    baseSalary,
    commissionRate,
    salesVolume: aggregateSales,
    commissionEarned,
    salesTarget,
    targetMet,
    targetBonus,
    totalGrossPayable
  };
};
